function subscribeSignal(kind){
 if(sample||csvMode){toast('샘플/CSV에서는 신호 감시를 등록하지 않습니다. 실제 시세에 연결하세요.');return;}
 try{const next=validateRule({id:uid(),name:`${marketTitle(symbol)} · ${interval} · ${kind==='apex-signal'?'APEX 점수필터':'APEX 후보 전체'}`,symbol,interval,kind,signalSettings:{...signalSettings},components:{...componentVisibility},once:false,enabled:true,lastEvaluated:null,armedAt:Date.now()});
 if(rules.length>=200)throw new Error('알람은 최대200개입니다.');
 if(kind==='apex-signal'&&(!chartContext||!calculateApexSignals(candles,chartContext,signalSettings).at(-1)?.signalReady))throw new Error('실제 시세와 확정 상위 시간봉이 준비된 자체 차트에서 등록하세요.');
 const same=rules.find(r=>r.enabled&&r.kind===kind&&r.symbol===symbol&&r.interval===interval&&JSON.stringify(kind==='apex-signal'?r.signalSettings:r.components)===JSON.stringify(kind==='apex-signal'?next.signalSettings:next.components));if(same){toast('같은 설정의 시그널 반복 알람이 이미 켜져 있습니다.');return;}
 rules.push(next);saveRules();renderAlerts();monitor();toast('등록 완료 · 이후 확정봉의 롱/숏 시그널마다 반복 알람. 창 종료·절전 중 전달은 보장되지 않습니다.');
 }catch(e){toast(e.message);}
}
